={{ 
  (() => {
    const o = $("LLM: normalize message").first().json.output;

    let msg = o.slack_message;

    const score = Number(String(o.closeness_score).split("/")[0]);

    if (score >= 80) {
      msg += "\n\n*Супровідний лист:*\n" + o.cover_letter;
    }

    msg += "\n\n📊 *Аналіз резюме:*";
    msg += "\n*Релевантність:* " + o.relevance_overall + "/100";
    msg += " (Навички: " + o.relevance_skills + " | Досвід: " + o.relevance_experience + " | ATS: " + o.relevance_ats + ")";

    let actions = o.improvement_actions;
    if (typeof actions === 'string') {
      try { actions = JSON.parse(actions); } catch(e) { actions = []; }
    }

    if (actions && actions.length > 0) {
      msg += "\n\n✅ *Дії:*";
      actions.forEach(a => {
        msg += "\n• " + a.action + " (" + a.timeframe + ")";
      });
    }

    if (o.summary) {
      msg += "\n\n💡 *Підсумок:* " + o.summary;
    }

    return msg;
  })()
}}

