parameters.jsCode:
const text = $input.first().json.text || '';

// Extract job IDs from LinkedIn URLs
const jobIdRegex = /linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/g;
const seen = new Set();
const urls = [];

let match;
while ((match = jobIdRegex.exec(text)) !== null) {
  const jobId = match[1];
  if (!seen.has(jobId)) {
    seen.add(jobId);
    urls.push(`https://www.linkedin.com/jobs/view/${jobId}`);
  }
}

return [{ json: { directUrls: urls } }];
